class SqrtDecomposition {
  constructor(arr) {
    this.arr = arr.slice();
    this.n = arr.length;
    this.blockSize = Math.max(1, Math.floor(Math.sqrt(this.n)));
    this.blockCount = Math.ceil(this.n / this.blockSize);
    this.blockSum = new Array(this.blockCount).fill(0);
    for (let i = 0; i < this.n; i++) {
      this.blockSum[Math.floor(i / this.blockSize)] += arr[i];
    }
  }

  update(i, value) {
    const block = Math.floor(i / this.blockSize);
    this.blockSum[block] += value - this.arr[i];
    this.arr[i] = value;
  }

  queryRangeSum(l, r) {
    let sum = 0;
    let i = l;
    while (i <= r) {
      const block = Math.floor(i / this.blockSize);
      const blockStart = block * this.blockSize;
      const blockEnd = Math.min(blockStart + this.blockSize - 1, this.n - 1);

      if (blockStart === i && blockEnd <= r) {
        sum += this.blockSum[block];   // whole block fits inside [l, r] - O(1)
        i = blockEnd + 1;
      } else {
        sum += this.arr[i];            // partial block - scan element by element
        i++;
      }
    }
    return sum;
  }
}
